const CATEGORY_META = {
  "Zuivel": ["🥛","Zuivel"], "Kaas":["🧀","Kaas"], "Ei":["🥚","Ei"], "Groenten":["🥕","Groenten"], "Fruit":["🍌","Fruit"],
  "Vlees":["🥩","Vlees"], "Vis":["🐟","Vis"], "Noten":["🥜","Noten"], "Pitten & zaden":["🌱","Pitten & zaden"],
  "Granen & wafels":["🌾","Granen & wafels"], "Peulvruchten":["🫘","Peulvruchten"], "Proteïne":["💪","Proteïne"],
  "Olie & vet":["🫒","Olie & vet"], "Extra's":["🍯","Extra's"]
};
const MEALS=[['breakfast','Ontbijt','☀️'],['lunch','Lunch','🥗'],['dinner','Diner','🍽️'],['snack','Tussendoor','🍎']];
const LS='balance.v1';
const DEFAULTS={
  version:1,
  goals:{kcal:2200,protein:140,carbs:220,fat:70,fiber:30,water:2500,steps:10000,restingBurn:1500,activeDeduction:20,targetWeight:null,netCarbs:false},
  foods:[], productOverrides:{}, hiddenProducts:[], logs:{}, activity:{}, water:{}, workouts:[], weights:[], recipes:[], favorites:[], recent:[], settings:{showSourceBadges:true}, draft:null
};
let state=loadState();
let route={name:'today',params:{}};

function clone(x){return JSON.parse(JSON.stringify(x));}
function loadState(){
  try{const raw=localStorage.getItem(LS); if(!raw) return clone(DEFAULTS); const x=JSON.parse(raw); return {...clone(DEFAULTS),...x,goals:{...DEFAULTS.goals,...(x.goals||{})},settings:{...DEFAULTS.settings,...(x.settings||{})}};}catch(e){return clone(DEFAULTS)}
}
function save(){localStorage.setItem(LS,JSON.stringify(state));}
function allProducts(){
  const hidden=new Set(state.hiddenProducts||[]);
  const seeds=SEED_PRODUCTS.filter(p=>!hidden.has(p.id)).map(p=>state.productOverrides?.[p.id]?{...p,...state.productOverrides[p.id],custom:false,edited:true}:p);
  return [...seeds,...(state.foods||[]).filter(p=>!hidden.has(p.id))];
}
function todayISO(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`;}
function fmtDate(iso){const d=new Date(iso+'T12:00:00');return d.toLocaleDateString('nl-NL',{weekday:'short',day:'numeric',month:'short'});}
function n(v,d=0){const x=Number(v);return Number.isFinite(x)?x:d;}
function f(v,dec=0){return n(v).toLocaleString('nl-NL',{maximumFractionDigits:dec,minimumFractionDigits:dec});}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function uid(p='id'){return p+'_'+Date.now().toString(36)+Math.random().toString(36).slice(2,7)};
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2200)}
function mealLabel(k){return (MEALS.find(x=>x[0]===k)||['',k])[1]}
function mealIcon(k){return (MEALS.find(x=>x[0]===k)||['','', '🍽️'])[2]}
function getDay(iso=todayISO()){if(!state.logs[iso]) state.logs[iso]={}; return state.logs[iso];}
function entriesFor(iso,meal){return (state.logs[iso]&&state.logs[iso][meal])||[];}
function macros(entries){return entries.reduce((a,e)=>{for(const k of ['kcal','protein','carbs','fat','fiber'])a[k]+=n(e.snapshot[k]);return a},{kcal:0,protein:0,carbs:0,fat:0,fiber:0});}
function dayMacros(iso=todayISO()){return macros(MEALS.flatMap(m=>entriesFor(iso,m[0])))}
function activityFor(iso=todayISO()){return state.activity[iso]||{steps:0,activeKcal:0};}
function energyFor(iso=todayISO()){const m=dayMacros(iso),a=activityFor(iso);const corrected=n(a.activeKcal)*(1-n(state.goals.activeDeduction)/100);const burn=n(state.goals.restingBurn)+corrected;return {intake:m.kcal,corrected,burn,balance:m.kcal-burn};}
function amountSnapshot(p,amount){const factor=n(amount)/100;return {kcal:n(p.kcal)*factor,protein:n(p.protein)*factor,carbs:n(p.carbs)*factor,fat:n(p.fat)*factor,fiber:n(p.fiber)*factor,sugars:n(p.sugars)*factor,satFat:n(p.satFat)*factor,salt:n(p.salt)*factor};}
function productById(id){return allProducts().find(p=>p.id===id)}
function conversionFactor(p){const s=(p.name+' '+p.state).toLowerCase();if(s.includes('rijst'))return 2.6;if(s.includes('quinoa'))return 3.5;if(s.includes('bulgur'))return 3.5;if(s.includes('couscous'))return 3;if(p.category==='Peulvruchten' && !/blik|pot|diepvries|uitlek/.test(s))return 2.5;return null;}
function conversionText(p,amount){const fac=conversionFactor(p);if(!fac||!amount)return '';const st=p.state.toLowerCase();if(/droog|onbereid/.test(st)){return `${f(amount,1)} g droog ≈ ${f(amount*fac,0)} g bereid (richtwaarde ×${String(fac).replace('.',',')})`;}if(/gekookt|bereid/.test(st)){return `${f(amount,1)} g bereid ≈ ${f(amount/fac,1)} g droog equivalent (richtwaarde)`;}return '';}
function routeTo(name,params={}){route={name,params};location.hash='#'+name;render();window.scrollTo(0,0)}
function currentDate(){return route.params.date||todayISO()}
function setHeader(title,actions=''){document.getElementById('headerSubtitle').textContent=title;document.getElementById('headerActions').innerHTML=actions;}
function setActiveNav(name){document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.route===name || (name.startsWith('builder')&&b.dataset.route==='add')))}
function render(){
  setActiveNav(route.name);
  const view=document.getElementById('view');
  const fn={today:renderToday,add:renderAddStart,builder:renderBuilder,builderCategory:renderBuilderCategory,cart:renderCart,agenda:renderAgenda,weight:renderWeight,more:renderMore,products:renderProducts,recipes:renderRecipes,trends:renderTrends,goals:renderGoals,history:renderHistory,settings:renderSettings}[route.name]||renderToday;
  view.innerHTML=fn();bindCommon();
}
function bindCommon(){document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>routeTo(x.dataset.go));document.querySelectorAll('[data-back]').forEach(x=>x.onclick=()=>history.back());}

function renderToday(){
  const iso=currentDate(),m=dayMacros(iso),e=energyFor(iso),a=activityFor(iso),water=n(state.water[iso]);
  setHeader(fmtDate(iso),`<button class="icon-btn" id="datePrev">‹</button><button class="icon-btn" id="dateNext">›</button>`);
  setTimeout(()=>{document.getElementById('datePrev').onclick=()=>shiftDate(-1);document.getElementById('dateNext').onclick=()=>shiftDate(1)},0);
  const bal=e.balance; const balTxt=bal<0?`${f(Math.abs(bal))} kcal tekort`:`${f(bal)} kcal overschot`;
  return `<section class="section card hero"><div class="section-title"><h2>Energiebalans</h2><span class="badge">schatting</span></div><div class="metric"><span>Gegeten</span><b>${f(m.kcal)} kcal</b></div><div class="metric"><span>Geschatte verbranding</span><b>${f(e.burn)} kcal</b></div><div class="metric"><span>Balans</span><b>${balTxt}</b></div><div class="kpi-row">${kpi('Eiwit',m.protein,state.goals.protein,'g')}${kpi('KH',m.carbs,state.goals.carbs,'g')}${kpi('Vet',m.fat,state.goals.fat,'g')}${kpi('Vezels',m.fiber,state.goals.fiber,'g')}</div><div class="subtle" style="margin-top:10px">Actieve kcal worden standaard met ${f(state.goals.activeDeduction)}% gecorrigeerd. Dit blijft een schatting.</div></section>
  <section class="section"><div class="section-title"><h2>Maaltijden</h2><button class="ghost-btn" data-go="add">＋ toevoegen</button></div><div class="grid">${MEALS.map(mm=>mealCard(iso,mm)).join('')}</div></section>
  <section class="section grid two"><div class="card"><div class="section-title"><h2>Water</h2><span>💧</span></div><div style="font-size:28px;font-weight:800">${f(water)} ml</div><div class="progress" style="margin:8px 0"><span style="width:${Math.min(100,water/n(state.goals.water,1)*100)}%"></span></div><button class="secondary" id="water250">+ 250 ml</button></div>
  <div class="card"><div class="section-title"><h2>Activiteit</h2><span>👟</span></div><div class="metric"><span>Stappen</span><b>${f(a.steps)}</b></div><div class="metric"><span>Actieve kcal</span><b>${f(a.activeKcal)}</b></div><button class="secondary" id="activityEdit">Bewerken</button></div></section>`;
}
function kpi(label,val,goal,unit){const pct=Math.min(100,n(val)/Math.max(1,n(goal))*100);return `<div class="kpi"><span class="subtle">${label}</span><strong>${f(val,0)}${unit}</strong><div class="progress"><span style="width:${pct}%"></span></div></div>`}
function mealCard(iso,mm){const x=macros(entriesFor(iso,mm[0]));return `<div class="card meal-card"><div><h3>${mm[2]} ${mm[1]}</h3><div><b>${f(x.kcal)} kcal</b></div><div class="macro-line">${f(x.protein,0)}g eiwit · ${f(x.carbs,0)}g KH · ${f(x.fat,0)}g vet</div></div><button class="meal-add" data-mealadd="${mm[0]}">＋</button></div>`}
function shiftDate(delta){const d=new Date(currentDate()+'T12:00:00');d.setDate(d.getDate()+delta);route.params.date=todayISO(d);render()}

function renderAddStart(){setHeader('Maaltijd toevoegen');return `<section class="section"><div class="section-title"><h2>Kies maaltijdmoment</h2></div><div class="grid two">${MEALS.map(m=>`<button class="category-card" data-startmeal="${m[0]}"><span class="cat-icon">${m[2]}</span><b>${m[1]}</b><span class="subtle">Live samenstellen</span></button>`).join('')}</div></section><section class="section"><div class="section-title"><h2>Snel</h2></div><div class="grid two"><button class="category-card" data-go="recipes"><span class="cat-icon">⭐</span><b>Eigen recepten</b><span class="subtle">Herbruikbare combinaties</span></button><button class="category-card" id="recentStart"><span class="cat-icon">🕘</span><b>Recente producten</b><span class="subtle">Start met recent gebruikt</span></button></div></section>`}
function startDraft(meal,iso=todayISO()){state.draft={id:uid('draft'),date:iso,meal,items:[],createdAt:Date.now()};save();routeTo('builder')}
function draft(){return state.draft}
function ensureDraft(){if(!state.draft){startDraft('breakfast');return false}return true}
function renderBuilder(){if(!state.draft){setTimeout(()=>routeTo('add'),0);return ''}const d=draft();setHeader(`${mealIcon(d.meal)} ${mealLabel(d.meal)}`,`<button class="ghost-btn" id="cancelDraft">Annuleer</button>`);const counts={};d.items.forEach(i=>{const p=productById(i.productId);if(p)counts[p.category]=(counts[p.category]||0)+1});const cats=Object.keys(CATEGORY_META).filter(c=>allProducts().some(p=>p.category===c));return `<section class="section"><div class="section-title"><h2>Kies categorie</h2><span class="badge">🛒 ${d.items.length}</span></div><div class="category-grid">${cats.map(c=>{const [ico,label]=CATEGORY_META[c];return `<button class="category-card" data-cat="${esc(c)}"><span class="cat-icon">${ico}</span><b>${label}</b><span class="subtle">${counts[c]?`✓ ${counts[c]} gekozen`:`${allProducts().filter(p=>p.category===c).length} producten`}</span></button>`}).join('')}</div></section>${d.items.length?`<div class="sticky-action"><button class="primary" style="width:100%" id="reviewCart">🛒 Bekijk ${mealLabel(d.meal).toLowerCase()} · ${d.items.length} product${d.items.length===1?'':'en'}</button></div>`:''}`}
function renderBuilderCategory(){if(!state.draft){setTimeout(()=>routeTo('add'),0);return ''}const cat=route.params.category;const products=filterAllowed(allProducts().filter(p=>p.category===cat));setHeader(`${CATEGORY_META[cat]?.[0]||'•'} ${cat}`,`<button class="ghost-btn" id="toBuilder">Categorieën</button>`);return `<div class="toolbar"><input id="productSearch" class="search" placeholder="Zoek in ${esc(cat)}"><button class="icon-btn" id="showFav">★</button></div><div class="product-list" id="productList">${products.map(productRow).join('')}</div><div class="sticky-action"><button class="primary" style="width:100%" id="addSelected">Toevoegen aan maaltijd</button></div>`}
function filterAllowed(ps){return ps.filter(p=>!(/snoep|chocolade/i.test(p.name)&&p.category!== 'Groenten'));}
function productRow(p){const existing=draft()?.items.find(i=>i.productId===p.id);const fav=state.favorites.includes(p.id);const warning=p.halalStatus.includes('verifiëren')?`<span class="badge warn">halal controleren</span>`:'';return `<div class="product-row" data-product-row="${p.id}"><div class="product-head"><input type="checkbox" data-check="${p.id}" ${existing?'checked':''}><div class="product-main"><b>${p.brand?esc(p.brand)+' · ':''}${esc(p.name)}</b><div class="meta">${esc(p.state)} · ${f(p.kcal)} kcal · ${f(p.protein,1)}g eiwit /100${p.unit}</div><div class="pill-row">${warning}${p.labelRule?`<span class="badge">${esc(p.labelRule.split(';')[0])}</span>`:''}</div></div><button class="icon-btn" data-fav="${p.id}" aria-label="Favoriet">${fav?'★':'☆'}</button></div><div class="amount-wrap ${existing?'':'hidden'}" data-amountwrap="${p.id}"><input type="number" min="0" step="0.1" inputmode="decimal" data-amount="${p.id}" value="${existing?existing.amount:''}" placeholder="gram"><span>${p.unit}</span><div style="flex:1"><div class="conversion-note ${existing&&conversionText(p,existing.amount)?'':'hidden'}" data-conv="${p.id}">${existing?conversionText(p,existing.amount):''}</div></div></div></div>`}
function renderCart(){if(!state.draft){setTimeout(()=>routeTo('add'),0);return ''}const d=draft(),mac=macros(d.items);setHeader(`Controle · ${mealLabel(d.meal)}`,`<button class="ghost-btn" id="backBuilder">Categorieën</button>`);return `<section class="section card"><div class="section-title"><h2>🛒 ${mealLabel(d.meal)}</h2><span>${d.items.length} producten</span></div>${d.items.map(i=>`<div class="cart-line"><div><b>${esc(i.name)}</b><br><small>${f(i.amount,1)} ${i.unit} · ${f(i.snapshot.kcal)} kcal</small></div><button class="icon-btn" data-edititem="${i.productId}">✎</button><button class="icon-btn" data-removeitem="${i.productId}">×</button></div>`).join('')}<div class="cart-total"><div class="metric"><span>Totaal</span><b>${f(mac.kcal)} kcal</b></div><div class="metric"><span>Eiwit</span><b>${f(mac.protein,1)} g</b></div><div class="metric"><span>Koolhydraten</span><b>${f(mac.carbs,1)} g</b></div><div class="metric"><span>Vet</span><b>${f(mac.fat,1)} g</b></div><div class="metric"><span>Vezels</span><b>${f(mac.fiber,1)} g</b></div></div></section><section class="section card"><div class="section-title"><h2>Optioneel bewaren</h2></div><div class="field"><label>Naam eigen recept</label><input id="recipeName" placeholder="Bijv. standaard ontbijt"></div><div class="subtle" style="margin-top:7px">Leeg laten als je deze combinatie niet als recept wilt bewaren.</div></section><div class="form-actions"><button class="secondary" id="addMore">Product toevoegen</button><button class="primary" id="saveMeal">Maaltijd opslaan</button></div>`}

function renderAgenda(){setHeader('Trainingsagenda',`<button class="primary" id="newWorkout">＋ Training</button>`);const ws=[...state.workouts].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `<section class="section"><div class="section-title"><h2>Trainingen</h2></div>${ws.length?`<div class="list">${ws.map(w=>`<div class="list-item"><div class="row"><div><h3>${esc(w.title)}</h3><div class="meta">${fmtDate(w.date)} · ${esc(w.time||'tijd n.v.t.')} · ${f(w.duration)} min · ${esc(w.intensity)}</div></div><span class="badge">${esc(w.status)}</span></div><div class="pill-row"><span class="pill">${esc(w.type)}</span>${w.note?`<span class="pill">${esc(w.note)}</span>`:''}</div><div class="form-actions" style="margin-top:10px"><button class="secondary" data-editworkout="${w.id}">Bewerken</button><button class="danger-btn" data-delworkout="${w.id}">Verwijderen</button></div></div>`).join('')}</div>`:`<div class="card empty"><span class="big">🏋️</span>Nog geen trainingen gepland.</div>`}</section>`}
function renderWeight(){setHeader('Gewicht',`<button class="primary" id="addWeight">＋ Meting</button>`);const ws=[...state.weights].sort((a,b)=>a.date.localeCompare(b.date));const latest=ws.at(-1);const d7=weightDiff(ws,7),d30=weightDiff(ws,30);return `<section class="section grid three"><div class="card"><div class="subtle">Laatste</div><b style="font-size:23px">${latest?f(latest.kg,1)+' kg':'—'}</b></div><div class="card"><div class="subtle">7 dagen</div><b style="font-size:23px">${d7===null?'—':signed(d7)+' kg'}</b></div><div class="card"><div class="subtle">30 dagen</div><b style="font-size:23px">${d30===null?'—':signed(d30)+' kg'}</b></div></section><section class="section card"><div class="section-title"><h2>7-daags gemiddelde</h2></div>${weightChart(ws)}</section><section class="section"><div class="list">${[...ws].reverse().slice(0,30).map(w=>`<div class="list-item"><div class="row"><b>${fmtDate(w.date)}</b><span>${f(w.kg,1)} kg</span></div><div class="form-actions" style="margin-top:8px"><button class="danger-btn" data-delweight="${w.date}">Verwijderen</button></div></div>`).join('')}</div></section>`}
function weightDiff(ws,days){if(ws.length<2)return null;const latest=ws.at(-1),cut=new Date(latest.date+'T12:00:00');cut.setDate(cut.getDate()-days);const earlier=[...ws].reverse().find(w=>new Date(w.date+'T12:00:00')<=cut);return earlier?latest.kg-earlier.kg:null}
function signed(v){return (v>0?'+':'')+f(v,1)}
function movingAverage(ws,i){const slice=ws.slice(Math.max(0,i-6),i+1);return slice.reduce((s,x)=>s+n(x.kg),0)/slice.length}
function weightChart(ws){if(!ws.length)return `<div class="empty">Nog geen gewichtsdata.</div>`;const pts=ws.slice(-90);const av=pts.map((x,i)=>({date:x.date,v:movingAverage(pts,i)}));return svgLine(av.map(x=>x.v),av.map(x=>x.date))}
function svgLine(vals,labels){if(!vals.length)return '';const W=600,H=220,p=28,min=Math.min(...vals),max=Math.max(...vals),span=Math.max(.1,max-min);const xy=vals.map((v,i)=>[p+(W-2*p)*(i/Math.max(1,vals.length-1)),H-p-(H-2*p)*((v-min)/span)]);const path=xy.map((q,i)=>(i?'L':'M')+q[0].toFixed(1)+' '+q[1].toFixed(1)).join(' ');const area=`M ${xy[0][0]} ${H-p} `+xy.map(q=>`L ${q[0]} ${q[1]}`).join(' ')+` L ${xy.at(-1)[0]} ${H-p} Z`;return `<svg class="svg-chart" viewBox="0 0 ${W} ${H}" role="img"><line class="chart-grid" x1="${p}" y1="${p}" x2="${p}" y2="${H-p}"/><line class="chart-grid" x1="${p}" y1="${H-p}" x2="${W-p}" y2="${H-p}"/><path class="chart-area" d="${area}"/><path class="chart-line" d="${path}"/><text class="chart-label" x="${p}" y="16">${f(max,1)}</text><text class="chart-label" x="${p}" y="${H-5}">${f(min,1)}</text><text class="chart-label" x="${W-p-70}" y="${H-5}">${labels.at(-1)||''}</text></svg>`}

function renderMore(){setHeader('Meer');const items=[['products','🥕','Producten','Bibliotheek & eigen producten'],['recipes','⭐','Eigen recepten','Opgeslagen combinaties'],['trends','⌁','Trends','7 / 30 / 90 dagen'],['goals','◎','Doelen','Macro’s, water & energie'],['history','🕘','Historie','Daglogs terugkijken'],['settings','⚙','Instellingen','Back-up, import & PWA']];return `<div class="more-grid">${items.map(i=>`<button class="more-btn" data-go="${i[0]}"><span class="ico">${i[1]}</span><b>${i[2]}</b><span class="subtle">${i[3]}</span></button>`).join('')}</div>`}
function renderProducts(){setHeader('Producten',`<button class="primary" id="newProduct">＋ Product</button>`);return `<div class="toolbar"><input id="allProductSearch" class="search" placeholder="Zoek product, merk of categorie"><span class="badge">${allProducts().length}</span></div><div id="allProductList" class="product-list">${allProducts().slice(0,100).map(productBrowseRow).join('')}</div>`}
function productBrowseRow(p){return `<div class="product-row"><div class="product-main"><b>${p.brand?esc(p.brand)+' · ':''}${esc(p.name)}</b><div class="meta">${esc(p.category)} · ${esc(p.state)} · ${f(p.kcal)} kcal · P ${f(p.protein,1)} · KH ${f(p.carbs,1)} · V ${f(p.fat,1)} /100${p.unit}</div><div class="pill-row">${p.custom?'<span class="badge">eigen product</span>':''}${p.edited?'<span class="badge">aangepast</span>':''}${p.sourceStatus?`<span class="pill">${esc(p.sourceStatus)}</span>`:''}</div>${p.note?`<div class="conversion-note">${esc(p.note)}</div>`:''}<div class="form-actions" style="margin-top:9px"><button class="secondary" data-editproduct="${p.id}">Bewerken</button>${p.edited&&!p.custom?`<button class="ghost-btn" data-resetproduct="${p.id}">Herstel standaard</button>`:''}${p.custom?`<button class="danger-btn" data-delproduct="${p.id}">Verwijderen</button>`:''}</div></div></div>`}
function renderRecipes(){setHeader('Eigen recepten');return `<section class="section">${state.recipes.length?`<div class="list">${state.recipes.map(r=>{const m=macros(r.items);return `<div class="list-item"><div class="row"><div><h3>${esc(r.name)}</h3><div class="meta">${r.items.length} ingrediënten · ${f(m.kcal)} kcal</div></div><button class="primary" data-userecipe="${r.id}">Gebruik</button></div><div class="form-actions" style="margin-top:10px"><button class="danger-btn" data-delrecipe="${r.id}">Verwijderen</button></div></div>`}).join('')}</div>`:`<div class="card empty"><span class="big">⭐</span>Nog geen eigen recepten. Stel eerst een maaltijd samen en kies bij het opslaan een receptnaam.</div>`}</section>`}
function renderTrends(){setHeader('Trends');const days=n(route.params.days,30);const stats=trendStats(days);return `<div class="toolbar">${[7,30,90].map(d=>`<button class="${days===d?'primary':'secondary'}" data-days="${d}">${d} dagen</button>`).join('')}</div><section class="section grid two"><div class="card"><div class="subtle">Gem. intake</div><b style="font-size:22px">${f(stats.avgIntake)} kcal</b></div><div class="card"><div class="subtle">Gem. verbranding</div><b style="font-size:22px">${f(stats.avgBurn)} kcal</b></div><div class="card"><div class="subtle">Gem. balans</div><b style="font-size:22px">${signed(stats.avgBalance)} kcal</b></div><div class="card"><div class="subtle">Gem. eiwit</div><b style="font-size:22px">${f(stats.avgProtein,1)} g</b></div><div class="card"><div class="subtle">Trainingen</div><b style="font-size:22px">${stats.trainingCount}</b></div><div class="card"><div class="subtle">Gewicht</div><b style="font-size:22px">${stats.weightChange===null?'—':signed(stats.weightChange)+' kg'}</b></div></section><section class="section card"><div class="section-title"><h2>Gewichtstrend</h2><span class="badge">7-daags gemiddelde</span></div>${weightChart(state.weights.filter(w=>new Date(w.date)>=stats.start))}</section><div class="warning-box">Trends en energiebalans zijn schattingen en geen medisch advies.</div>`}
function trendStats(days){const end=new Date(todayISO()+'T23:59:59'),start=new Date(end);start.setDate(start.getDate()-days+1);let intake=[],burn=[],bal=[],protein=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+1)){const iso=todayISO(d),m=dayMacros(iso),e=energyFor(iso);intake.push(m.kcal);burn.push(e.burn);bal.push(e.balance);protein.push(m.protein)}const avg=a=>a.reduce((s,x)=>s+x,0)/Math.max(1,a.length);const inRangeW=state.weights.filter(w=>new Date(w.date+'T12:00:00')>=start&&new Date(w.date+'T12:00:00')<=end);return {start,avgIntake:avg(intake),avgBurn:avg(burn),avgBalance:avg(bal),avgProtein:avg(protein),trainingCount:state.workouts.filter(w=>new Date(w.date+'T12:00:00')>=start&&new Date(w.date+'T12:00:00')<=end&&w.status!=='Geannuleerd').length,weightChange:inRangeW.length>1?inRangeW.at(-1).kg-inRangeW[0].kg:null}}
function renderGoals(){setHeader('Doelen');const g=state.goals;return `<section class="section card"><div class="form-grid">${goalField('kcal','Dagelijkse kcal','kcal',g.kcal)}${goalField('protein','Eiwit','g',g.protein)}${goalField('carbs','Koolhydraten','g',g.carbs)}${goalField('fat','Vet','g',g.fat)}${goalField('fiber','Vezels','g',g.fiber)}${goalField('water','Water','ml',g.water)}${goalField('steps','Stappen','',g.steps)}${goalField('restingBurn','Conservatieve rustverbranding','kcal',g.restingBurn)}${goalField('activeDeduction','Correctie smartwatch actieve kcal','%',g.activeDeduction)}${goalField('targetWeight','Doelgewicht (optioneel)','kg',g.targetWeight??'')}<div class="field"><label>Netto koolhydraten</label><select id="goal_netCarbs"><option value="false" ${!g.netCarbs?'selected':''}>Koolhydraten niet corrigeren</option><option value="true" ${g.netCarbs?'selected':''}>Koolhydraten - vezels</option></select></div></div><div class="form-actions" style="margin-top:14px"><button class="primary" id="saveGoals">Doelen opslaan</button></div></section>`}
function goalField(k,l,u,v){return `<div class="field"><label>${l}${u?` (${u})`:''}</label><input id="goal_${k}" type="number" step="0.1" value="${v}"></div>`}
function renderHistory(){setHeader('Historie');const dates=Object.keys(state.logs).sort().reverse();return `<section class="section">${dates.length?`<div class="list">${dates.map(iso=>{const m=dayMacros(iso);return `<button class="list-item" style="text-align:left;width:100%" data-historydate="${iso}"><div class="row"><b>${fmtDate(iso)}</b><span>${f(m.kcal)} kcal</span></div><div class="meta">P ${f(m.protein,0)}g · KH ${f(m.carbs,0)}g · V ${f(m.fat,0)}g</div></button>`}).join('')}</div>`:`<div class="card empty">Nog geen historie.</div>`}</section>`}
function renderSettings(){setHeader('Instellingen');return `<section class="section card"><div class="section-title"><h2>Lokale gegevens</h2></div><p class="subtle">Balance heeft geen account, cloud of backend. Je gegevens staan alleen in deze browser via localStorage.</p><div class="form-actions"><button class="primary" id="exportData">Back-up exporteren</button><label class="secondary" style="cursor:pointer">Back-up importeren<input id="importData" type="file" accept="application/json" hidden></label></div></section><section class="section card"><div class="section-title"><h2>PWA / offline</h2></div><div id="pwaState" class="ok-box">Service worker-status controleren…</div></section><section class="section card"><div class="section-title"><h2>Data wissen</h2></div><button class="danger-btn" id="resetAll">Alle lokale data verwijderen</button></section>`}

function modal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modal').classList.add('show')}
function closeModal(){document.getElementById('modal').classList.remove('show')}
function workoutForm(w={}){modal(`<h2>${w.id?'Training bewerken':'Training toevoegen'}</h2><div class="form-grid"><div class="field"><label>Type</label><select id="w_type">${['Gym','Boksen','Cardio','Wandelen','Overig'].map(x=>`<option ${w.type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Titel</label><input id="w_title" value="${esc(w.title||'')}"></div><div class="grid two"><div class="field"><label>Datum</label><input id="w_date" type="date" value="${w.date||todayISO()}"></div><div class="field"><label>Tijd</label><input id="w_time" type="time" value="${w.time||''}"></div></div><div class="grid two"><div class="field"><label>Duur (min)</label><input id="w_duration" type="number" value="${w.duration||60}"></div><div class="field"><label>Intensiteit</label><select id="w_intensity">${['Laag','Midden','Hoog'].map(x=>`<option ${w.intensity===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>Status</label><select id="w_status">${['Gepland','Gedaan','Geannuleerd'].map(x=>`<option ${w.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Notitie</label><textarea id="w_note">${esc(w.note||'')}</textarea></div></div><div class="form-actions" style="margin-top:14px"><button class="secondary" id="mCancel">Annuleer</button><button class="primary" id="wSave">Opslaan</button></div>`);document.getElementById('mCancel').onclick=closeModal;document.getElementById('wSave').onclick=()=>{const o={id:w.id||uid('w'),type:v('w_type'),title:v('w_title').trim()||'Training',date:v('w_date'),time:v('w_time'),duration:n(v('w_duration')),intensity:v('w_intensity'),status:v('w_status'),note:v('w_note').trim()};state.workouts=state.workouts.filter(x=>x.id!==o.id);state.workouts.push(o);save();closeModal();render();toast('Training opgeslagen')}}
function productForm(existing=null){
 const isEdit=!!existing, p=existing||{};
 modal(`<h2>${isEdit?'Product bewerken':'Eigen product toevoegen'}</h2><div class="form-grid"><div class="field"><label>Categorie</label><select id="p_cat">${Object.keys(CATEGORY_META).map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Productnaam</label><input id="p_name" value="${esc(p.name||'')}"></div><div class="field"><label>Merk (optioneel)</label><input id="p_brand" value="${esc(p.brand||'')}"></div><div class="field"><label>Toestand</label><input id="p_state" value="${esc(p.state||'')}" placeholder="bijv. rauw / gekookt / ready-to-use"></div><div class="field"><label>Eenheid</label><select id="p_unit"><option value="g" ${(p.unit||'g')==='g'?'selected':''}>g</option><option value="ml" ${p.unit==='ml'?'selected':''}>ml</option></select></div><div class="grid two">${['kcal','protein','carbs','fat','fiber','sugars','satFat','salt'].map(k=>`<div class="field"><label>${{kcal:'kcal',protein:'Eiwit g',carbs:'KH g',fat:'Vet g',fiber:'Vezels g',sugars:'Suikers g',satFat:'Verzadigd g',salt:'Zout g'}[k]} /100${p.unit||'g'}</label><input id="p_${k}" type="number" step="0.01" value="${p[k]??0}"></div>`).join('')}</div><div class="field"><label>Bron / URL (optioneel)</label><input id="p_source" value="${esc(p.source||'')}"></div><div class="field"><label>Bronstatus</label><input id="p_sourceStatus" value="${esc(p.sourceStatus||'Handmatig aangepast')}"></div><div class="field"><label>Notitie</label><textarea id="p_note">${esc(p.note||'')}</textarea></div><div class="warning-box">Wijzigingen gelden voor nieuwe registraties. Eerder opgeslagen maaltijden houden hun historische voedingswaarden.</div></div><div class="form-actions" style="margin-top:14px"><button class="secondary" id="mCancel">Annuleer</button><button class="primary" id="pSave">${isEdit?'Wijzigingen opslaan':'Toevoegen'}</button></div>`);
 document.getElementById('mCancel').onclick=closeModal;
 document.getElementById('pSave').onclick=()=>{
   if(!v('p_name').trim())return toast('Vul een productnaam in');
   const updated={category:v('p_cat'),name:v('p_name').trim(),brand:v('p_brand').trim(),state:v('p_state').trim()||'ready-to-use',unit:v('p_unit')||'g',kcal:n(v('p_kcal')),protein:n(v('p_protein')),carbs:n(v('p_carbs')),fat:n(v('p_fat')),fiber:n(v('p_fiber')),sugars:n(v('p_sugars')),satFat:n(v('p_satFat')),salt:n(v('p_salt')),halalStatus:p.halalStatus||'door gebruiker toegevoegd - zelf verifiëren',labelRule:p.labelRule||'',sourceStatus:v('p_sourceStatus').trim()||'Handmatig aangepast',source:v('p_source').trim(),note:v('p_note').trim(),editedAt:new Date().toISOString()};
   if(isEdit){
     if(p.custom){const idx=state.foods.findIndex(x=>x.id===p.id); if(idx>=0)state.foods[idx]={...state.foods[idx],...updated,custom:true};}
     else {state.productOverrides=state.productOverrides||{};state.productOverrides[p.id]=updated;}
   } else {state.foods.push({id:uid('USR'),...updated,custom:true});}
   save();closeModal();render();toast(isEdit?'Product aangepast':'Product toegevoegd');
 };
}

function v(id){return document.getElementById(id)?.value||''}

// Event delegation
addEventListener('click',e=>{
 const b=e.target.closest('button,[data-route]'); if(!b)return;
 if(b.matches('.nav-btn')){routeTo(b.dataset.route);return}
 if(b.dataset.mealadd){startDraft(b.dataset.mealadd,currentDate());return}
 if(b.dataset.startmeal){startDraft(b.dataset.startmeal);return}
 if(b.dataset.cat){routeTo('builderCategory',{category:b.dataset.cat});return}
 if(b.dataset.fav){const id=b.dataset.fav;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();render();return}
 if(b.dataset.edititem){const p=productById(b.dataset.edititem);routeTo('builderCategory',{category:p.category});return}
 if(b.dataset.removeitem){state.draft.items=state.draft.items.filter(i=>i.productId!==b.dataset.removeitem);save();render();return}
 if(b.dataset.editworkout){workoutForm(state.workouts.find(x=>x.id===b.dataset.editworkout));return}
 if(b.dataset.delworkout){if(confirm('Training verwijderen?')){state.workouts=state.workouts.filter(x=>x.id!==b.dataset.delworkout);save();render()}return}
 if(b.dataset.delweight){if(confirm('Gewichtsmeting verwijderen?')){state.weights=state.weights.filter(x=>x.date!==b.dataset.delweight);save();render()}return}
 if(b.dataset.editproduct){productForm(productById(b.dataset.editproduct));return}
 if(b.dataset.resetproduct){if(confirm('Standaardwaarden van dit product herstellen?')){if(state.productOverrides)delete state.productOverrides[b.dataset.resetproduct];save();render();toast('Standaard hersteld')}return}
 if(b.dataset.delproduct){if(confirm('Eigen product verwijderen?')){state.foods=state.foods.filter(x=>x.id!==b.dataset.delproduct);save();render()}return}
 if(b.dataset.userecipe){useRecipe(state.recipes.find(r=>r.id===b.dataset.userecipe));return}
 if(b.dataset.delrecipe){if(confirm('Recept verwijderen?')){state.recipes=state.recipes.filter(r=>r.id!==b.dataset.delrecipe);save();render()}return}
 if(b.dataset.days){route.params.days=n(b.dataset.days);render();return}
 if(b.dataset.historydate){routeTo('today',{date:b.dataset.historydate});return}
});
addEventListener('change',e=>{if(e.target.matches('[data-check]')){const id=e.target.dataset.check;document.querySelector(`[data-amountwrap="${id}"]`)?.classList.toggle('hidden',!e.target.checked)}});
addEventListener('input',e=>{if(e.target.matches('[data-amount]')){const id=e.target.dataset.amount,p=productById(id),el=document.querySelector(`[data-conv="${id}"]`),txt=conversionText(p,n(e.target.value));if(el){el.textContent=txt;el.classList.toggle('hidden',!txt)}}});

function bindDynamic(){
 const q=id=>document.getElementById(id);
 if(q('water250'))q('water250').onclick=()=>{const iso=currentDate();state.water[iso]=n(state.water[iso])+250;save();render()};
 if(q('activityEdit'))q('activityEdit').onclick=()=>activityModal(currentDate());
 if(q('cancelDraft'))q('cancelDraft').onclick=()=>{if(confirm('Huidige maaltijd wissen?')){state.draft=null;save();routeTo('add')}};
 if(q('toBuilder'))q('toBuilder').onclick=()=>routeTo('builder');
 if(q('reviewCart'))q('reviewCart').onclick=()=>routeTo('cart');
 if(q('backBuilder'))q('backBuilder').onclick=()=>routeTo('builder');
 if(q('addMore'))q('addMore').onclick=()=>routeTo('builder');
 if(q('productSearch'))q('productSearch').oninput=()=>searchCategory(q('productSearch').value);
 if(q('showFav'))q('showFav').onclick=()=>{const rows=[...document.querySelectorAll('[data-product-row]')];rows.forEach(r=>r.classList.toggle('hidden',!state.favorites.includes(r.dataset.productRow)))};
 if(q('addSelected'))q('addSelected').onclick=addSelectedToDraft;
 if(q('saveMeal'))q('saveMeal').onclick=saveDraftMeal;
 if(q('newWorkout'))q('newWorkout').onclick=()=>workoutForm();
 if(q('addWeight'))q('addWeight').onclick=weightModal;
 if(q('newProduct'))q('newProduct').onclick=productForm;
 if(q('allProductSearch'))q('allProductSearch').oninput=()=>browseProducts(q('allProductSearch').value);
 if(q('saveGoals'))q('saveGoals').onclick=saveGoals;
 if(q('exportData'))q('exportData').onclick=exportData;
 if(q('importData'))q('importData').onchange=importData;
 if(q('resetAll'))q('resetAll').onclick=resetAll;
 if(q('pwaState'))updatePWAState();
 if(q('recentStart'))q('recentStart').onclick=()=>{startDraft('breakfast');setTimeout(()=>{const recent=state.recent.slice(0,20);if(!recent.length)return toast('Nog geen recente producten');routeTo('builderCategory',{category:productById(recent[0])?.category||'Zuivel'})},0)};
}
const oldRender=render;render=function(){oldRender();bindDynamic()};
function searchCategory(term){const t=term.trim().toLowerCase();document.querySelectorAll('[data-product-row]').forEach(r=>{const p=productById(r.dataset.productRow);r.classList.toggle('hidden',!!t&&!`${p.name} ${p.brand} ${p.state}`.toLowerCase().includes(t))})}
function addSelectedToDraft(){const selected=[...document.querySelectorAll('[data-check]:checked')];if(!selected.length)return toast('Selecteer minimaal één product');for(const ch of selected){const id=ch.dataset.check,p=productById(id),input=document.querySelector(`[data-amount="${id}"]`),amount=n(input?.value);if(amount<=0)return toast(`Vul gram in voor ${p.name}`);const item={productId:id,name:(p.brand?p.brand+' · ':'')+p.name,amount,unit:p.unit,snapshot:amountSnapshot(p,amount),addedAt:Date.now()};state.draft.items=state.draft.items.filter(x=>x.productId!==id);state.draft.items.push(item);state.recent=[id,...state.recent.filter(x=>x!==id)].slice(0,30)}save();toast(`${selected.length} product(en) toegevoegd`);routeTo('builder')}
function saveDraftMeal(){const d=draft();if(!d||!d.items.length)return;const day=getDay(d.date);day[d.meal]=(day[d.meal]||[]).concat(d.items.map(i=>({...i,entryId:uid('entry')})));const rn=v('recipeName').trim();if(rn){state.recipes.push({id:uid('recipe'),name:rn,items:clone(d.items),createdAt:Date.now()})}state.draft=null;save();toast('Maaltijd opgeslagen');routeTo('today',{date:d.date})}
function useRecipe(r){if(!r)return;modal(`<h2>${esc(r.name)}</h2><p class="subtle">Kies maaltijdmoment. Daarna kun je de hoeveelheden nog aanpassen.</p><div class="grid two">${MEALS.map(m=>`<button class="category-card" data-recipemeal="${m[0]}"><span class="cat-icon">${m[2]}</span><b>${m[1]}</b></button>`).join('')}</div>`);document.querySelectorAll('[data-recipemeal]').forEach(b=>b.onclick=()=>{state.draft={id:uid('draft'),date:todayISO(),meal:b.dataset.recipemeal,items:clone(r.items),createdAt:Date.now()};save();closeModal();routeTo('cart')})}
function activityModal(iso){const a=activityFor(iso);modal(`<h2>Activiteit · ${fmtDate(iso)}</h2><div class="form-grid"><div class="field"><label>Stappen</label><input id="a_steps" type="number" value="${a.steps}"></div><div class="field"><label>Smartwatch actieve kcal</label><input id="a_kcal" type="number" value="${a.activeKcal}"></div><div class="warning-box">Balance past daarna ${f(state.goals.activeDeduction)}% conservatieve correctie toe.</div></div><div class="form-actions" style="margin-top:14px"><button class="secondary" id="mCancel">Annuleer</button><button class="primary" id="aSave">Opslaan</button></div>`);q('mCancel').onclick=closeModal;q('aSave').onclick=()=>{state.activity[iso]={steps:n(v('a_steps')),activeKcal:n(v('a_kcal'))};save();closeModal();render()}}
function q(id){return document.getElementById(id)}
function weightModal(){const iso=todayISO(),existing=state.weights.find(w=>w.date===iso);modal(`<h2>Gewicht ${fmtDate(iso)}</h2><div class="field"><label>Gewicht (kg)</label><input id="kg" type="number" step="0.05" value="${existing?existing.kg:''}"></div><div class="subtle" style="margin-top:7px">Maximaal één meting per dag.</div><div class="form-actions" style="margin-top:14px"><button class="secondary" id="mCancel">Annuleer</button><button class="primary" id="kgSave">Opslaan</button></div>`);q('mCancel').onclick=closeModal;q('kgSave').onclick=()=>{const kg=n(v('kg'));if(kg<=0)return toast('Vul een geldig gewicht in');state.weights=state.weights.filter(w=>w.date!==iso);state.weights.push({date:iso,kg});state.weights.sort((a,b)=>a.date.localeCompare(b.date));save();closeModal();render();toast('Gewicht opgeslagen')}}
function browseProducts(term){const t=term.trim().toLowerCase();const ps=allProducts().filter(p=>!t||`${p.name} ${p.brand} ${p.category} ${p.state}`.toLowerCase().includes(t)).slice(0,200);q('allProductList').innerHTML=ps.map(productBrowseRow).join('')}
function saveGoals(){for(const k of ['kcal','protein','carbs','fat','fiber','water','steps','restingBurn','activeDeduction','targetWeight'])state.goals[k]=v('goal_'+k)===''?(k==='targetWeight'?null:0):n(v('goal_'+k));state.goals.netCarbs=v('goal_netCarbs')==='true';save();toast('Doelen opgeslagen');render()}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`balance-backup-${todayISO()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function importData(e){const file=e.target.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(r.result);if(!x||typeof x!=='object')throw 0;if(!confirm('Huidige lokale data vervangen door deze back-up?'))return;state={...clone(DEFAULTS),...x,goals:{...DEFAULTS.goals,...(x.goals||{})}};save();toast('Back-up geïmporteerd');routeTo('today')}catch{toast('Ongeldig back-upbestand')}};r.readAsText(file)}
function resetAll(){if(confirm('Weet je zeker dat je alle lokale Balance-data wilt wissen?')){localStorage.removeItem(LS);state=clone(DEFAULTS);toast('Alle lokale data gewist');routeTo('today')}}
async function updatePWAState(){const el=q('pwaState');if(!('serviceWorker'in navigator)){el.textContent='Service workers worden niet ondersteund in deze browser.';el.className='warning-box';return}try{const reg=await navigator.serviceWorker.getRegistration();el.textContent=reg?'Offline service worker actief. Balance kan na de eerste succesvolle laadbeurt offline functioneren.':'Service worker wordt bij de eerste online laadbeurt geregistreerd.';el.className=reg?'ok-box':'warning-box'}catch{}}

// Close modal by backdrop
q('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});
// hash/back behavior
addEventListener('hashchange',()=>{const name=location.hash.replace('#','');if(name&&name!==route.name){route={name,params:{}};render()}});
// PWA
if('serviceWorker'in navigator) addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
// Start
route={name:location.hash.replace('#','')||'today',params:{}};render();
